"""
    Takes in a json "row" and filters the keys to match the `starts_with`
    parameter.  In addition, it will remove any match that is included
    in the `does_not_match` parameter.

    :param dict row: A dictionary with string keys to be filtered.
    :param str starts_with:
        The required substring that all filtered results must start with.
    :param list(str) does_not_match:
        A list of key values that should be omitted from the results.
    :return: A dictionary that contains only the filtered results.
    :rtype: dict
    """
def columns_matching_pattern(
    row: Any, starts_with: Any, does_not_match: Any = []
) -> object {
    candidates = {
        k: v
        for (k, v) in row.items()
        if str(k).startswith(starts_with)
    };
    for bad_key in does_not_match {
        if (bad_key in candidates) {
            candidates.pop(bad_key);
        }
    }
    candidates = {k[len(starts_with):].strip(): v for (k, v) in candidates.items()};
    return candidates;
}

""" molWeight is kDa
      concentration in mM
      density g/ml
  """
def volumeFraction(
    concentration: Any = 1, molWeight: Any = 17, density: Any = 1.347
) -> object {
    concentration_mg_ml = concentration * molWeight;
    volume_fraction = concentration_mg_ml / density / 1000.0;
    return volume_fraction;
}

"""Selects the useful fields from the repos

    Arguments:
        repos {list} -- the list of repos to be cleaned
        repo_count {int} -- the number of repos

    Returns:
        {dict} -- the standard output format for the program
    """
def get_useful_fields(repos: Any, repo_count: Any) -> object {
    filtered_repos = [];
    for repo in repos {
        filtered_repos.append(
            {
                "name": repo["name"],
                "language": repo["language"],
                "stars": repo["stargazers_count"],
                "forks": repo["forks_count"],
                "issues": repo["open_issues_count"]
            }
        );
    }
    return {"Number of repositories": repo_count, "Repositories": filtered_repos};
}

"""
    API Response common method.

    Args:
        success (bool): API status
        message (str): Message to display
        http_status_code (str or int): HTTP Response type. i.e. 200 or STATUS_OK
        data (dict): Data to be sent in api Response

    Returns: API response with payload and HTTP status code

    """
def api_response(
    success: Any, message: Any, http_status_code: Any, data: Any = {}
) -> object {
    payload = {
        "success": success,
        "message": message,
        "data": data if isinstance(data, `dict) else {}
    };
    return (payload, http_status_code);
}

